import{_ as t,o as i,c as l,a0 as e}from"./chunks/framework.D0gLf8u5.js";const _=JSON.parse('{"title":"云族纪是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":null}'),o={name:"guide/introduction.md"};function r(n,a,s,d,u,c){return i(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="云族纪是什么" tabindex="-1">云族纪是什么？ <a class="header-anchor" href="#云族纪是什么" aria-label="Permalink to &quot;云族纪是什么？&quot;">​</a></h1><p>云族纪是一个<strong>家族族谱应用</strong>，但它和你见过的其他族谱软件不太一样。</p><h2 id="传统族谱软件的问题" tabindex="-1">传统族谱软件的问题 <a class="header-anchor" href="#传统族谱软件的问题" aria-label="Permalink to &quot;传统族谱软件的问题&quot;">​</a></h2><p>大部分族谱工具画的是一棵&quot;树&quot;——从上到下，父传子、子传孙。这在传统父系社会里够用，但现实中的家族关系比树复杂得多：</p><ul><li>一个人可能嫁过来、又嫁过去，同时在两个家族里有身份</li><li>表亲、姻亲、外亲——这些关系在纯父系树上根本画不出来</li><li>录错了一个人，删也不是、改也不是，因为数据已经牵连到其他人了</li></ul><h2 id="云族纪的思路" tabindex="-1">云族纪的思路 <a class="header-anchor" href="#云族纪的思路" aria-label="Permalink to &quot;云族纪的思路&quot;">​</a></h2><p>云族纪不是画一棵树，而是<strong>记录一张关系网</strong>：</p><ul><li><strong>父系谱系是骨架</strong>——按辈分、排行、血缘排列</li><li><strong>配偶和外亲是延伸</strong>——嫁过来的人有配偶身份，外嫁的人有外家身份</li><li><strong>分身机制</strong>——一个真人在不同家族有不同的节点，通过分身关联起来</li><li><strong>归档可逆</strong>——任何操作都有快照，误操作可以撤销</li></ul><h2 id="适合谁用" tabindex="-1">适合谁用？ <a class="header-anchor" href="#适合谁用" aria-label="Permalink to &quot;适合谁用？&quot;">​</a></h2><ul><li>想记录自己家族成员关系的人</li><li>觉得传统族谱软件太死板、画不出真实关系的人</li><li>担心录错数据无法挽回的人</li></ul><h2 id="不适合谁用" tabindex="-1">不适合谁用？ <a class="header-anchor" href="#不适合谁用" aria-label="Permalink to &quot;不适合谁用？&quot;">​</a></h2><ul><li>想要一棵完美的、整齐的树——云族纪画的是网</li><li>想公开给所有人看——云族纪是私有部署，只给自家人用</li><li>想要 SaaS 一键注册即用——需要自己部署 uniCloud 空间</li></ul>',12)])])}const p=t(o,[["render",r]]);export{_ as __pageData,p as default};
